155	u64 soft_combine_private_data(unsigned int dev_id, unsigned int user_id,
156	    unsigned int node_type, unsigned int node_id, unsigned int sensor_id)
157	{
158	    u64 private_data;
159	
160	    private_data = (((u64)(dev_id & SF_MASK_16BIT) << SF_OFFSET_48BIT)    |                      \
161	                    ((u64)(user_id & SF_MASK_16BIT) << SF_OFFSET_32BIT)   |                      \
162	                    ((u64)(node_type & SF_MASK_16BIT) << SF_OFFSET_16BIT) |                      \
163	                    ((u64)(node_id & SF_MASK_8BIT) << SF_OFFSET_8BIT)     |                      \
164	                    ((u64)(sensor_id & SF_MASK_8BIT)));
165	    return private_data;
166	}
