168	
169	STATIC int soft_add_fault_event(struct soft_error_list *error_new, struct soft_event *event_queue)
170	{
171	    struct soft_error_list *pos = NULL;
172	    struct soft_error_list *n = NULL;
173	
174	    if ((event_queue == NULL) || (error_new == NULL)) {
175	        soft_drv_err("invalid para. event_queue or error_new is NULL\n");
176	        return -EINVAL;
177	    }
178	
179	    ka_task_mutex_lock(&event_queue->mutex);
180	    ka_list_for_each_entry_safe(pos, n, &event_queue->error_list.list, list) {
181	        if ((pos->error.sensor_type == error_new->error.sensor_type) &&
182	            (pos->error.err_type == error_new->error.err_type)) {
183	            if (pos->report_status == EVENT_REPORT_RECOVERED) {
184	                pos->report_status = EVENT_REPORT_INIT;
185	            }
186	            ka_task_mutex_unlock(&event_queue->mutex);
187	            return EVENT_EXIST; /* It means found fault event already in event list, don't need add */
188	        }
189	    }
190	    ka_list_add(&error_new->list, &event_queue->error_list.list); /* add new event to queue */
191	    event_queue->error_num++;
192	    error_new->report_status = EVENT_REPORT_INIT;
193	    ka_task_mutex_unlock(&event_queue->mutex);
194	
195	    return 0;
196	}
197	
198	/*
199	 * true means the queued event should be removed when the corresponding processing stage arrives.
200	 * For example, EVENT_REPORT_RECOVERED + EVENT_REPORT_SCANNED is true because recover arrives before
201	 * the first scan, so the event should be reported once in scan and then removed from the queue.
202	 */
203	STATIC const bool err_report_status_table[EVENT_REPORT_STATUS_MAX][EVENT_REPORT_STATUS_MAX] = {
204	/* row: report_status           col: process_status */
205	/* ------------------------------------------------ */
206	/*                              EVENT_REPORT_INIT   EVENT_REPORT_SCANNED EVENT_REPORT_RECOVERED */
207	/* EVENT_REPORT_INIT */         {false,             false,               false},
208	/* EVENT_REPORT_SCANNED */      {false,             false,               true},
209	/* EVENT_REPORT_RECOVERED */    {false,             true,                false},
210	};
211	
212	STATIC bool check_error_report_status(EVENT_REPORT_STATUS err_status, EVENT_REPORT_STATUS process_status)
213	{
214	    if (err_status >= EVENT_REPORT_STATUS_MAX || process_status >= EVENT_REPORT_STATUS_MAX) {
215	        return false;
216	    }
217	
218	    return err_report_status_table[err_status][process_status];
219	}
220	
221	STATIC bool is_soft_fault_recover(struct soft_event *event_queue, struct soft_fault *event_new)
222	{
223	    bool recover_flag = false;
224	    struct soft_error_list *pos = NULL;
225	    struct soft_error_list *n = NULL;
226	    struct soft_fault *event = NULL;
227	
228	    ka_task_mutex_lock(&event_queue->mutex);
229	    ka_list_for_each_entry_safe(pos, n, &event_queue->error_list.list, list) {
230	        event = &pos->error;
231	        if ((event->err_type == event_new->err_type) && (event->assertion == GENERAL_EVENT_TYPE_OCCUR)) {
232	            if (check_error_report_status(pos->report_status, EVENT_REPORT_RECOVERED)) {
233	                ka_list_del(&pos->list);
234	                dbl_kfree(pos);
235	                pos = NULL;
236	                event_queue->error_num--;
237	            } else {
238	                pos->report_status = EVENT_REPORT_RECOVERED;
239	            }
240	            recover_flag = true;
241	        }
242	    }
243	    ka_task_mutex_unlock(&event_queue->mutex);
244	
245	    return recover_flag;
246	}
