248	STATIC struct soft_event *soft_event_queue_get(struct soft_dev_client *client, unsigned int node_type,
249	    unsigned int node_id, unsigned int idx)
250	{
251	    struct soft_dev *pos = NULL;
252	    struct soft_dev *n = NULL;
253	    struct soft_event *event_queue = NULL;
254	
255	    ka_list_for_each_entry_safe(pos, n, &client->head, list) {
256	        if (pos->dev_node.node_type == node_type && pos->node_id == node_id) {
257	            event_queue = &pos->sensor_event_queue[idx];
258	            break;
259	        }
260	    }
261	
262	    return event_queue;
263	}
264	
265	int soft_fault_event_scan(unsigned long long private_data, struct dms_sensor_event_data *data)
266	{
267	    int ret;
268	    unsigned int dev_id, user_id, node_type, node_id, idx;
269	    struct soft_dev_client *client = NULL;
270	    struct soft_error_list *pos = NULL;
271	    struct soft_error_list *n = NULL;
272	    struct soft_event *event_queue = NULL;
273	    struct soft_fault *event = NULL;
274	    struct drv_soft_ctrl *soft_ctrl = soft_get_ctrl();
275	
276	    dev_id = private_data >> SF_OFFSET_48BIT;
277	    user_id = (private_data & SF_MASK_48BIT) >> SF_OFFSET_32BIT;
278	    node_type = (private_data & SF_MASK_32BIT) >> SF_OFFSET_16BIT;
279	    node_id = (private_data & SF_MASK_16BIT) >> SF_OFFSET_8BIT;
280	    idx = private_data & SF_MASK_8BIT;
281	
282	    if ((data == NULL) || (dev_id >= ASCEND_DEV_MAX_NUM) || (user_id >= SF_USER_MAX) || (idx >= SF_SUB_ID_MAX)) {
283	        soft_drv_err("invalid para. (dev_id=%u; s_id=%u; node_type=0x%x; idx=%u)\n", dev_id, user_id, node_type, idx);
284	        return -EINVAL;
285	    }
286	
287	    client = soft_ctrl->s_dev_t[dev_id][user_id];
288	    event_queue = soft_event_queue_get(client, node_type, node_id, idx);
289	    if (event_queue == NULL) {
290	        soft_drv_err("get event_queue failed. (dev_id=%u; node_id=%u; idx=%u)\n", dev_id, node_id, idx);
291	        return -EINVAL;
292	    }
293	
294	    data->event_count = 0;
295	    ka_task_mutex_lock(&event_queue->mutex);
296	    /* get every event of the sensor event queue */
297	    ka_list_for_each_entry_safe(pos, n, &event_queue->error_list.list, list) {
298	        event = &pos->error;
299	        data->sensor_data[data->event_count].current_value = event->err_type;
300	        data->sensor_data[data->event_count].data_size = event->data_len;
301	        ret = memcpy_s(data->sensor_data[data->event_count].event_data, DMS_MAX_EVENT_DATA_LENGTH,
302	            event->data, event->data_len);
303	        if (ret != 0) {
304	            soft_drv_warn("memcpy_s failed, continue. (ret=%d)\n", ret);
305	            continue;
306	        }
307	
308	        if ((event->assertion == GENERAL_EVENT_TYPE_ONE_TIME) ||
309	            check_error_report_status(pos->report_status, EVENT_REPORT_SCANNED)) { /*  notification_event check. */
310	            ka_list_del(&pos->list);
311	            dbl_kfree(pos);
312	            pos = NULL;
313	            event_queue->error_num--;
314	        } else {
315	            pos->report_status = EVENT_REPORT_SCANNED;
316	        }
317	        data->event_count++;
318	        if (data->event_count == DMS_MAX_SENSOR_EVENT_COUNT) {
319	            break;
320	        }
321	    }
322	    ka_task_mutex_unlock(&event_queue->mutex);
323	
324	    return 0;
325	}
326	KA_EXPORT_SYMBOL(soft_fault_event_scan);
327	
328	int soft_fault_event_handler(struct soft_fault *event)
329	{
330	    int ret;
331	    struct soft_dev_client *client = NULL;
332	    struct soft_event *event_queue = NULL;
333	    struct soft_error_list *error_new = NULL;
334	    struct drv_soft_ctrl *soft_ctrl = soft_get_ctrl();
335	
336	    if (event == NULL) {
337	        soft_drv_err("invalid para, event is NULL.\n");
338	        return -EINVAL;
339	    }
340	
341	    if ((event->dev_id >= ASCEND_DEV_MAX_NUM) || (event->user_id >= SF_USER_MAX) || (event->sub_id >= SF_SUB_ID_MAX)) {
342	        soft_drv_err("invalid para. (dev_id=%u; user_id=%u; node_type=0x%x; idx=%u)\n",
343	            event->dev_id, event->user_id, event->node_type, event->sub_id);
344	        return -EINVAL;
345	    }
346	
347	    client = soft_ctrl->s_dev_t[event->dev_id][event->user_id];
348	    event_queue = soft_event_queue_get(client, event->node_type, event->node_id, event->sub_id);
349	    if (event_queue == NULL) {
350	        soft_drv_err("get event_queue failed. (dev_id=%u; node_type=0x%x; node_id=%u; idx=%u)\n",
351	            event->node_type, event->dev_id, event->node_id, event->sub_id);
352	        return -EINVAL;
353	    }
354	
355	    if (event->assertion == GENERAL_EVENT_TYPE_RESUME) {
356	        if (is_soft_fault_recover(event_queue, event)) {
357	            soft_drv_event("fault recover. "
358	                "(dev_id=%u; user_id=%u; assertion=%u; node_type=0x%x; sensor_type=0x%x; err_type=0x%x)\n",
359	                event->dev_id, event->user_id, event->assertion, event->node_type, event->sensor_type, event->err_type);
360	            return 0;
361	        }
362	        soft_drv_warn("Not found existing err_type or assertion. "
363	            "(dev_id=%u; user_id=%u; assertion=%u; node_type=0x%x; sensor_type=0x%x; err_type=0x%x)\n",
364	            event->dev_id, event->user_id, event->assertion, event->node_type, event->sensor_type, event->err_type);
365	        return -EINVAL;
366	    }
367	    error_new = dbl_kzalloc(sizeof(struct soft_error_list), KA_GFP_KERNEL | __KA_GFP_ACCOUNT);
368	    if (error_new == NULL) {
369	        soft_drv_err("new_event ka_mm_kzalloc failed.\n");
370	        return -ENOMEM;
371	    }
372	
373	    ret = memcpy_s(&error_new->error, sizeof(struct soft_fault), event, sizeof(struct soft_fault));
374	    if (ret != 0) {
375	        soft_drv_err("new_event memcpy_s failed. (ret=%d)\n", ret);
376	        goto out;
377	    }
378	
379	    ret = soft_add_fault_event(error_new, event_queue);
380	    if (ret != 0) {
381	        soft_kfree(&error_new);
382	        return ret;
383	    }
384	
385	    return ret;
386	out:
387	    soft_kfree(&error_new);
388	    soft_drv_err("fault event handler error. (dev_id=%u; user_id=%u; err_type=0x%x)\n",
389	        event->dev_id, event->user_id, event->err_type);
390	    return ret;
391	}
392	KA_EXPORT_SYMBOL(soft_fault_event_handler);
393	
394	void soft_fault_event_free(struct soft_event *event_queue)
395	{
396	    struct soft_error_list *pos = NULL;
397	    struct soft_error_list *n = NULL;
398	
399	    if (event_queue == NULL) {
400	        soft_drv_warn("Invalid para, event_queue is NULL\n");
401	        return;
402	    }
403	
404	    ka_task_mutex_lock(&event_queue->mutex);
405	    ka_list_for_each_entry_safe(pos, n, &event_queue->error_list.list, list) {
406	        ka_list_del(&pos->list);
407	        dbl_kfree(pos);
408	        pos = NULL;
409	        event_queue->error_num--;
410	    }
411	    ka_task_mutex_unlock(&event_queue->mutex);
412	}
413	
414	int soft_register_one_node(struct soft_dev *s_dev)
415	{
416	    int ret;
417	    unsigned int i;
418	
419	    if (s_dev == NULL) {
420	        soft_drv_err("Invalid para, h_dev is NULL.\n");
421	        return -EINVAL;
422	    }
423	
424	    if (s_dev->registered == 1) {
425	        soft_drv_warn("soft_dev is registered. (dev_id=%u; registered=%u)\n", s_dev->dev_id, s_dev->registered);
426	        return 0;
427	    }
428	
429	    ret = dms_register_dev_node(&s_dev->dev_node);
430	    if (ret != 0) {
431	        soft_drv_err("soft_fault register dev_node failed. (ret=%d)\n", ret);
432	        return ret;
433	    }
434	
435	    for (i = 0; i < s_dev->sensor_obj_num; i++) {
436	        ret = dms_sensor_register(&s_dev->dev_node, &s_dev->sensor_obj_table[i]);
437	        if (ret != 0) {
438	            soft_drv_err("soft_fault register sensor failed. (s_idx=%u; ret=%d)\n", i, ret);
439	            goto out;
440	        }
441	        s_dev->sensor_obj_registered[i] = 1;
442	    }
443	
444	    s_dev->registered = 1;
445	    return 0;
446	out:
447	    if (i > 0) {
448	        (void)dms_sensor_node_unregister(&s_dev->dev_node);
449	    }
450	    (void)dms_unregister_dev_node(&s_dev->dev_node);
451	
452	    return ret;
453	}
