456	void soft_unregister_one_node(struct soft_dev *s_dev)
457	{
458	    int ret;
459	
460	    if (s_dev == NULL) {
461	        soft_drv_err("Invalid para, h_dev is NULL.\n");
462	        return;
463	    }
464	
465	    if (s_dev->registered == 0) {
466	        return;
467	    }
468	
469	    ret = dms_sensor_node_unregister(&s_dev->dev_node);
470	    if (ret != 0) {
471	        soft_drv_warn("soft_fault unregister sensor node failed. (ret=%d)\n", ret);
472	    }
473	
474	    ret = dms_unregister_dev_node(&s_dev->dev_node);
475	    if (ret != 0) {
476	        soft_drv_warn("soft_fault unregister dev node failed. (ret=%d)\n", ret);
477	    }
478	
479	    s_dev->registered = 0;
480	    return;
481	}
