483	void soft_free_one_node(struct soft_dev_client *client, unsigned int node_type)
484	{
485	    unsigned int i;
486	    struct soft_dev *pos = NULL;
487	    struct soft_dev *n = NULL;
488	
489	    if (client == NULL) {
490	        soft_drv_warn("invalid para, client is NULL.\n");
491	        return;
492	    }
493	
494	    ka_task_mutex_lock(&client->mutex);
495	    ka_list_for_each_entry_safe(pos, n, &client->head, list) {
496	        if ((pos->dev_node.node_type == node_type) && (pos->registered == 1)) {
497	            soft_unregister_one_node(pos);
498	            for (i = 0; i < SF_SUB_ID_MAX; i++) {
499	                if (pos->sensor_obj_registered[i] == 1) {
500	                    soft_fault_event_free(&pos->sensor_event_queue[i]);
501	                }
502	            }
503	            soft_one_dev_exit(pos);
504	            ka_list_del(&pos->list);
505	            dbl_kfree(pos);
506	            pos = NULL;
507	            client->node_num--;
508	            break;
509	        }
510	    }
511	
512	    if (client->node_num == 0) {
513	        client->pid = -1;
514	        client->user_id = 0;
515	        client->registered = 0;
516	    }
517	
518	    ka_task_mutex_unlock(&client->mutex);
519	    return;
520	}
521	KA_EXPORT_SYMBOL(soft_free_one_node);
