571	STATIC int soft_exit_notifier(ka_notifier_block_t *nb, unsigned long mode, void *data)
572	{
573	    ka_task_struct_t *task = (ka_task_struct_t *)data;
574	    (void)nb;
575	    (void)mode;
576	    /* This code ensures that soft_fault resource can be released when the process exit abnormally */
577	    if ((task != NULL) && ka_task_judge_mm(task) && (task->tgid != 0) && (task->tgid == task->pid) &&
578	        ascend_intf_is_pid_init(task->tgid, DAVINCI_INTF_MODULE_DMS)) {
579	        /* Only the process open davinci device is check. */
580	        soft_fault_release_prepare(task->tgid);
581	    }
582	
583	    return 0;
584	}
