591	{
592	    (void)nb;
593	    (void)data;
594	    switch (mode) {
595	        case URD_NOTIFIER_RELEASE_PREPARE:
596	            /* This code ensures that soft_fault resource can be released when the process exit normally */
597	            soft_fault_release_prepare(ka_task_get_current_tgid());
598	            break;
599	        default:
