650	STATIC int soft_ctrl_init(void)
651	{
652	    int i, j;
653	    struct drv_soft_ctrl *soft_ctrl = soft_get_ctrl();
654	
655	    for (i = 0; i < ASCEND_DEV_MAX_NUM; i++) {
656	        soft_ctrl->user_num[i] = 1;
657	        ka_task_mutex_init(&soft_ctrl->mutex[i]);
658	        for (j = 0; j < SF_USER_MAX; j++) {
659	            soft_ctrl->s_dev_t[i][j] = dbl_kzalloc(sizeof(struct soft_dev_client), KA_GFP_KERNEL);
660	            if (soft_ctrl->s_dev_t[i][j] == NULL) {
661	                soft_drv_err("Kzalloc s_dev_t failed. \n");
662	                return -ENOMEM;
663	            }
664	
665	            soft_ctrl->s_dev_t[i][j]->pid = -1;
666	            soft_ctrl->s_dev_t[i][j]->registered = 0;
667	            soft_ctrl->s_dev_t[i][j]->node_num = 0;
668	            ka_task_mutex_init(&soft_ctrl->s_dev_t[i][j]->mutex);
669	            KA_INIT_LIST_HEAD(&soft_ctrl->s_dev_t[i][j]->head);
670	        }
671	    }
672	
673	    return 0;
674	}
675	
676	STATIC void soft_ctrl_exit(void)
677	{
678	    int i, j;
679	    struct drv_soft_ctrl *soft_ctrl = soft_get_ctrl();
680	
681	    for (i = 0; i < ASCEND_DEV_MAX_NUM; i++) {
682	        for (j = 0; j < SF_USER_MAX; j++) {
683	            if (soft_ctrl->s_dev_t[i][j] != NULL) {
684	                ka_task_mutex_destroy(&soft_ctrl->s_dev_t[i][j]->mutex);
685	                soft_ctrl->s_dev_t[i][j]->node_num = 0;
686	                soft_ctrl->s_dev_t[i][j]->registered = 0;
687	                soft_ctrl->s_dev_t[i][j]->pid = -1;
688	                dbl_kfree(soft_ctrl->s_dev_t[i][j]);
689	                soft_ctrl->s_dev_t[i][j] = NULL;
690	            }
691	        }
692	        ka_task_mutex_destroy(&soft_ctrl->mutex[i]);
693	        soft_ctrl->user_num[i] = 0;
694	    }
695	
696	    return;
697	}
698	
699	int soft_init(void)
700	{
701	    int ret;
702	
703	    CALL_INIT_MODULE(soft_fault);
704	    ret = soft_ctrl_init();
705	    if (ret != 0) {
706	        soft_drv_err("Soft ctrl init failed. (ret=%d)\n", ret);
707	        goto SOFT_CTRL_FAIL;
708	    }
709	
710	#ifdef CFG_EDGE_HOST
711	    ret = ka_dfx_profile_event_register(KA_PROFILE_TASK_EXIT, &g_soft_exit_notifier);
712	#else
713	    /* Use the native kernel interfaces on the device */
714	    ret = profile_event_register(PROFILE_TASK_EXIT, &g_soft_exit_notifier);
715	#endif
716	    if (ret != 0) {
717	        soft_drv_err("register profile notifier failed. (ret=%d)\n", ret);
718	        goto SOFT_CTRL_FAIL;
719	    }
720	
721	    /* Register callback to the URD. When a process exits, the DMS node,
722	     * sensor, and aggregated fault data related to the process need
723	     * to be released. */
724	    ret = urd_register_notifier(&g_soft_urd_notifier);
725	    if (ret != 0) {
726	        soft_drv_err("register urd notifier failed. (ret=%d)\n", ret);
727	        goto URD_REGISTER_FAIL;
728	    }
729	
730	    ret = dms_register_notifier(&g_soft_notifier);
731	    if (ret != 0) {
732	        soft_drv_err("register dms notifier failed. (ret=%d)\n", ret);
733	        goto DMS_REGISTER_FAIL;
734	    }
735	
736	    soft_drv_info("soft event driver init success.\n");
737	    return 0;
738	
739	DMS_REGISTER_FAIL:
740	    (void)urd_unregister_notifier(&g_soft_urd_notifier);
741	URD_REGISTER_FAIL:
742	#ifdef CFG_EDGE_HOST
743	    (void)ka_dfx_profile_event_unregister(KA_PROFILE_TASK_EXIT, &g_soft_exit_notifier);
744	#else
745	    /* Use the native kernel interfaces on the device */
746	    (void)profile_event_unregister(PROFILE_TASK_EXIT, &g_soft_exit_notifier);
747	#endif
748	SOFT_CTRL_FAIL:
749	    soft_ctrl_exit();
750	    CALL_EXIT_MODULE(soft_fault);
751	    return ret;
752	}
753	DECLAER_FEATURE_AUTO_INIT(soft_init, FEATURE_LOADER_STAGE_5);
754	
755	void soft_exit(void)
756	{
757	    (void)dms_unregister_notifier(&g_soft_notifier);
758	#if (!defined CFG_EDGE_HOST) && (defined CFG_FEATURE_OS_INIT_EVENT) /* device side */
759	    os_dev_unregister();
760	#endif
761	#ifdef CFG_FEATURE_DRV_KERNEL_SOFT_EVENT
762	    drv_kernel_soft_fault_unregister();
763	#endif
764	    (void)urd_unregister_notifier(&g_soft_urd_notifier);
765	#ifdef CFG_EDGE_HOST
766	    (void)ka_dfx_profile_event_unregister(KA_PROFILE_TASK_EXIT, &g_soft_exit_notifier);
767	#else
768	    /* Use the native kernel interfaces on the device */
769	    (void)profile_event_unregister(PROFILE_TASK_EXIT, &g_soft_exit_notifier);
770	#endif
771	    soft_dev_exit();
772	    soft_ctrl_exit();
773	    CALL_EXIT_MODULE(soft_fault);
774	    soft_drv_info("soft event driver exit success.\n");
775	}
776	DECLAER_FEATURE_AUTO_UNINIT(soft_exit, FEATURE_LOADER_STAGE_5);
