245	            if ((soft_fault_check_user_role(user_role_cur, whitelist[i].user_acc)) &&
246	                (soft_fault_check_run_env(run_env_cur, whitelist[i].run_env)) &&
247	                (soft_fault_check_proc_name(proc_name_cur, whitelist[i].proc_name))) {
248	                return true;
249	            } else {
250	                continue;
251	            }
252	        }
253	    }
254	
255	    soft_drv_err("Check sensor whitelist fail. (node_type=0x%x; sensor_type=0x%x; user_role_cur=0x%x; "
256	                 "run_env_cur=0x%x; proc_name_cur=%s)\n",
257	                 node_type, sensor_type, user_role_cur, run_env_cur, proc_name_cur);
258	    return false;
259	}
