327	
328	    /* This is compatibility processing, when the caller not uses the extension field, 
329	     * set default event mask */
330	    if ((assert_event_mask == 0) && (deassert_event_mask == 0)) {
331	        soft_get_default_event_mask(cfg->sensor_type, &assert_event_mask, &deassert_event_mask);
