355	STATIC int user_dev_node_register(unsigned int dev_id, unsigned int user_id, struct soft_dev *user_node,
356	    struct dms_sensor_node_cfg *cfg, uint64_t *handle)
357	{
358	    int ret;
359	    unsigned int sensor_idx;
360	    struct dms_node_operations *soft_ops = soft_get_ops();
361	    struct dms_node s_node = SOFT_NODE_DEF(cfg->node_type, "user", dev_id, user_node->node_id, soft_ops);
362	
363	    if (user_node->sensor_obj_num >= SF_SUB_ID_MAX) {
364	        soft_drv_warn("exceed max sensor num. (dev_id=%u; sensor_obj_num=%u)\n", dev_id, user_node->sensor_obj_num);
365	        return -EBUSY;
366	    }
367	
368	    if (user_node->registered == 0) { /* dev_node register once only */
369	        user_node->dev_node = s_node;
370	        ret = snprintf_s(user_node->dev_node.node_name, DMS_MAX_DEV_NAME_LEN, DMS_MAX_DEV_NAME_LEN,
371	            "%02u_%02d_%03x_%.5s", dev_id, user_node->node_id, cfg->node_type, cfg->name);
372	        if (ret <= 0) {
373	            soft_drv_err("snprintf_s failed. (dev_id=%u; node_id=%u; ret=%d)\n", dev_id, user_node->node_id, ret);
374	            return ret;
375	        }
376	
377	        ret = dms_register_dev_node(&user_node->dev_node);
378	        if (ret != 0) {
379	            soft_drv_err("register dev_node failed. (dev_id=%u; user_name=%s; node_type=%u; ret=%d)\n",
380	                dev_id, ka_task_get_current_comm(), cfg->node_type, ret);
381	            return ret;
382	        }
383	    }
384	
385	    for (sensor_idx = 0; sensor_idx < SF_SUB_ID_MAX; sensor_idx++) {
386	        if ((user_node->sensor_obj_registered[sensor_idx]) &&
387	            (user_node->sensor_obj_table[sensor_idx].sensor_type == cfg->sensor_type) &&
388	            (ka_base_strcmp(user_node->sensor_obj_table[sensor_idx].sensor_name, cfg->name) == 0)) {
389	            soft_drv_warn("sensor already register. (dev_id=%u; sensor_type=0x%x; name=%s)\n",
390	                dev_id, cfg->sensor_type, cfg->name);
391	            goto OUT;
392	        }
393	    }
394	
395	    /* get the first free sensor table index */
396	    for (sensor_idx = 0; sensor_idx < SF_SUB_ID_MAX; sensor_idx++) {
397	        if (user_node->sensor_obj_registered[sensor_idx] == 0) {
398	            break;
399	        }
400	    }
401	
402	    if (sensor_idx >= SF_SUB_ID_MAX) {
403	        soft_drv_warn("exceed max sensor num. (dev_id=%u; sensor_idx=%u)\n", dev_id, sensor_idx);
404	        return -EBUSY;
405	    }
406	
407	    ret = user_sensor_register(user_node, cfg, user_id, sensor_idx); /* register a new sensor obj , index i */
408	    if (ret != 0) {
409	        soft_drv_err("user sensor register failed. "
410	            "(dev_id=%u, node_type=0x%x, sensor_type=0x%x, sensor_id=%u; ret=%d)\n",
411	            dev_id, cfg->node_type, cfg->sensor_type, sensor_idx, ret);
412	        goto ERROR;
413	    }
414	
415	    user_node->sensor_obj_registered[sensor_idx] = 1;
416	    user_node->sensor_obj_num++;
417	    user_node->registered = 1;
418	OUT:
419	    *handle = ((uint64_t)cfg->node_type << SF_OFFSET_32BIT) |
420	        (sensor_idx << SF_OFFSET_16BIT) | cfg->sensor_type;
421	    return 0;
422	ERROR:
423	    if (user_node->registered == 0) {
424	        (void)dms_unregister_dev_node(&user_node->dev_node);
425	    }
426	    return ret;
427	}
