501	{
502	    int ret;
503	    int first_register = 0;
504	    unsigned int user_id = 0;
505	    struct soft_dev_client *client = NULL;
506	    struct soft_dev *user_node = NULL;
507	    struct drv_soft_ctrl *soft_ctrl = soft_get_ctrl();
508	
509	    ka_task_mutex_lock(&soft_ctrl->mutex[dev_id]);
