538	        }
539	        goto out;
540	    }
541	
542	    soft_dev_client_add(client, user_node, user_id, &soft_ctrl->user_num[dev_id], first_register);
543	    SOFT_PRINT_REGISTER_LOG(client, user_node, cfg, handle, soft_ctrl->user_num[dev_id], first_register);
544	
545	out:
546	    ka_task_mutex_unlock(&soft_ctrl->mutex[dev_id]);
547	    return ret;
548	}
