635	static inline int sensor_event_state_convert_assertion(struct dms_sensor_object_cfg *obj_cfg, int event_data)
636	{
637	    if ((obj_cfg->assert_event_mask & (1 << event_data)) && !(obj_cfg->deassert_event_mask & (1 << event_data))) {
638	        return GENERAL_EVENT_TYPE_ONE_TIME;
639	    }
640	
641	    return GENERAL_EVENT_TYPE_OCCUR;
642	}
