644	STATIC int dms_update_sensor_state(unsigned int dev_id, uint64_t handle, int val, int assertion)
645	{
646	    int i, ret, event_type;
647	    unsigned int node_type, sensor_idx, sensor_type;
648	    struct soft_fault event = {0};
649	    struct dms_sensor_object_cfg *p_cfg = NULL;
650	    struct soft_dev_client *client = NULL;
651	    struct soft_dev *pos = NULL;
652	    struct soft_dev *n = NULL;
653	    struct soft_dev *user_node = NULL;
654	    struct drv_soft_ctrl *soft_ctrl = soft_get_ctrl();
655	
656	    ka_task_mutex_lock(&soft_ctrl->mutex[dev_id]);
657	    for (i = SF_SENSOR_USER; i < SF_USER_MAX; i++) {
658	        if ((soft_ctrl->s_dev_t[dev_id][i]->pid == ka_task_get_current_tgid()) && (soft_ctrl->s_dev_t[dev_id][i]->registered == 1)) {
659	            client = soft_ctrl->s_dev_t[dev_id][i];
660	            break;
661	        }
662	    }
663	
664	    SOFT_PARSE_HANDLE(node_type, sensor_idx, sensor_type, handle);
665	    if ((client == NULL) || (sensor_idx >= SF_SUB_ID_MAX)) {
666	        soft_drv_err("Invalid para. (dev_id=%u; handle=0x%llx; client=%u)\n", dev_id, handle, (client != NULL));
667	        ka_task_mutex_unlock(&soft_ctrl->mutex[dev_id]);
668	        return -EINVAL;
669	    }
670	
671	    ka_list_for_each_entry_safe(pos, n, &client->head, list) {
672	        if ((pos->dev_node.node_type == node_type) && (pos->registered == 1)) {
673	            user_node = pos;
674	            break;
675	        }
676	    }
677	
678	    if (user_node == NULL) {
679	        ka_task_mutex_unlock(&soft_ctrl->mutex[dev_id]);
680	        soft_drv_err("Can not find a matching node. (handle=%llu; node_type=0x%x; sensor_type=0x%x; sensor_idx=%u)\n",
681	            handle, node_type, sensor_type, sensor_idx);
682	        return -EINVAL;
683	    }
684	
685	    for (i = 0; i < SF_SUB_ID_MAX; i++) {
686	        if (!pos->sensor_obj_registered[i]) {
687	            continue;
688	        }
689	
690	        p_cfg = &user_node->sensor_obj_table[i];
691	        if ((p_cfg->sensor_type != sensor_type) || (i != sensor_idx)) {
692	            continue;
693	        }
694	
695	        event_type = sensor_event_state_convert_assertion(p_cfg, val);
696	        /* if not resume and event_type mismatched, it will return fail here. */
697	        if ((assertion != GENERAL_EVENT_TYPE_RESUME) && (event_type != assertion)) {
698	            ka_task_mutex_unlock(&soft_ctrl->mutex[dev_id]);
699	            soft_drv_err("The assertion type is mismatched. "
700	                "(devid=%u; handle=%llu; node_type=0x%x; sensor_type=0x%x; sensor_idx=%u; type0=0x%x; type1=0x%x)\n",
701	                dev_id, handle, node_type, sensor_type, sensor_idx, event_type, assertion);
702	            return -EINVAL;
703	        }
704	
705	        event.sensor_type = p_cfg->sensor_type;
706	        event.dev_id = dev_id;
707	        event.user_id = client->user_id;
708	        event.node_type = node_type;
709	        event.node_id = user_node->node_id;
710	        event.sub_id = i;
711	        event.err_type = val;
712	        event.assertion = (unsigned int)assertion;
713	        ret = soft_fault_event_handler(&event);
714	        if (ret == 0) {
715	            soft_drv_event("soft node update state success. (dev_id=%u; pid=%d; sensor_name=%s; user_id=%u;"
716	                " node_id=%u; node_type=0x%x; sensor_type=0x%x; val=%d; assertion=%d; handle=0x%llx)\n",
717	                dev_id, client->pid, p_cfg->sensor_name, client->user_id, user_node->node_id, node_type,
718	                sensor_type, val, assertion, handle);
719	        }
720	        break;
721	    }
722	
723	    ka_task_mutex_unlock(&soft_ctrl->mutex[dev_id]);
724	    return 0;
725	}
