727	int soft_node_register(void *feature, char *in, u32 in_len, char *out, u32 out_len)
728	{
729	    int ret;
730	    size_t name_len = 0;
731	    uint64_t handle = 0;
732	    u32 dev_id, phy_id, vfid;
733	    struct dms_sensor_user *arg = NULL;
