735	
736	    if ((in == NULL) || (in_len != sizeof(struct dms_sensor_user)) || (out == NULL) || (out_len != sizeof(uint64_t))) {
737	        soft_drv_err("Invalid para. (in_len=%u; out_len=%u)\n", in_len, out_len);
738	        return -EINVAL;
739	    }
740	
741	    arg = (struct dms_sensor_user *)in;
742	    dev_id = arg->dev_id;
743	    cfg = arg->cfg;
744	
745	    name_len = ka_base_strnlen(cfg.name, CFG_NAME_MAX_LENGTH);
746	    if (name_len >= CFG_NAME_MAX_LENGTH) {
747	        soft_drv_err("Cfg name is invalid, length of name should be less than 20. (len=%zu)\n", name_len);
748	        return -EINVAL;
749	    }
750	
751	    ret = soft_sensor_para_check(cfg);
752	    if (ret != 0) {
753	        soft_drv_err("Sensor cfg check failed. (dev_id=%u; node_type=%d; sensor_type=%d; ret=%d;)\n",
754	            dev_id, cfg.node_type, cfg.sensor_type, ret);
755	        return ret;
756	    }
757	
758	    ret = soft_trans_and_check_id(dev_id, &phy_id, &vfid);
759	    if (ret != 0) {
760	        soft_drv_err("can't transform dev_id. (dev_id=%u; ret=%d)\n", dev_id, ret);
761	        return ret;
762	    }
763	
764	    if (!soft_sensor_whitelist_check(phy_id, cfg.node_type, cfg.sensor_type)) {
765	        soft_drv_err("whitelist check fail. (dev_id=%u; phy_id=%u; node_type=0x%x; sensor_type=0x%x)\n", dev_id, phy_id,
766	                     cfg.node_type, cfg.sensor_type);
767	        return -EINVAL;
768	    }
769	
770	    ret = dms_soft_node_register(phy_id, &cfg, &handle);
771	    if (ret != 0) {
772	        soft_drv_err("register soft node failed. (dev_id=%u; ret=%d)\n", dev_id, ret);
773	        return ret;
774	    }
775	
776	    *(uint64_t *)out = handle;
777	
778	    return 0;
779	}
780	
781	int soft_node_unregister(void *feature, char *in, u32 in_len, char *out, u32 out_len)
782	{
783	    int ret;
784	    uint64_t handle;
785	    unsigned int phy_id, vfid;
786	    struct dms_sensor_user *arg = NULL;
787	    unsigned int node_type, sensor_idx, sensor_type;
788	
789	    if ((in == NULL) || (in_len != sizeof(struct dms_sensor_user))) {
790	        soft_drv_err("Invalid para. (in_len=%u)\n", in_len);
791	        return -EINVAL;
792	    }
793	
794	    arg = (struct dms_sensor_user *)in;
795	    handle = arg->handle;
796	
797	    ret = soft_trans_and_check_id(arg->dev_id, &phy_id, &vfid);
798	    if (ret != 0) {
799	        soft_drv_err("can't transform dev_id. (dev_id=%u; ret=%d)\n", arg->dev_id, ret);
800	        return ret;
801	    }
802	
803	    SOFT_PARSE_HANDLE(node_type, sensor_idx, sensor_type, handle);
804	    if (!soft_sensor_whitelist_check(phy_id, (unsigned short)node_type, (unsigned char)sensor_type)) {
805	        soft_drv_err("whitelist check fail. (dev_id=%u; phy_id=%u; node_type=0x%x; sensor_type=0x%x)\n", arg->dev_id,
806	                     phy_id, node_type, sensor_type);
807	        return -EINVAL;
808	    }
809	
810	    return dms_soft_node_unregister(phy_id, handle);
811	}
812	
813	int soft_node_update_state(void *feature, char *in, u32 in_len, char *out, u32 out_len)
814	{
815	    int ret, val, assertion;
816	    uint64_t handle;
817	    unsigned int phy_id, vfid;
818	    struct dms_sensor_user *arg = NULL;
819	
820	    if ((in == NULL) || (in_len != sizeof(struct dms_sensor_user))) {
821	        soft_drv_err("Invalid para. (in_is_null=%d; in_len=%u; valid_in_len=%zd)\n",
822	            (in == NULL), in_len, sizeof(struct dms_sensor_user));
823	        return -EINVAL;
824	    }
825	
826	    arg = (struct dms_sensor_user *)in;
827	    val = arg->value;
828	    assertion = arg->assertion;
829	    handle = arg->handle;
830	
831	    if (assertion >= GENERAL_EVENT_TYPE_MAX) {
832	        soft_drv_err("Invalid para. (dev_id=%u; assertion=%d; max=%d)\n",
833	            arg->dev_id, assertion, GENERAL_EVENT_TYPE_MAX - 1);
834	        return -EINVAL;
835	    }
836	
837	    ret = soft_trans_and_check_id(arg->dev_id, &phy_id, &vfid);
838	    if (ret != 0) {
839	        soft_drv_err("can't transform dev_id. (dev_id=%u; ret=%d)\n", arg->dev_id, ret);
840	        return ret;
841	    }
842	
843	    if (!soft_fault_whitelist_check(phy_id, handle, val)) {
844	        soft_drv_err("Fault whitelist check failed. (dev_id=%u; phy_id=%u; handle=0x%llx; val=%d)\n", arg->dev_id,
845	                     phy_id, handle, val);
846	        return -EINVAL;
847	    }
848	
849	    return dms_update_sensor_state(phy_id, handle, val, assertion);
850	}
851	
852	STATIC void soft_dev_free_registered_dev(struct soft_dev_client *client)
853	{
854	    int  i;
855	    struct soft_dev *pos = NULL;
856	    struct soft_dev *n = NULL;
857	    ka_list_for_each_entry_safe(pos, n, &client->head, list) {
858	        if (pos->registered == 0) {
859	            continue;
860	        }
861	        soft_unregister_one_node(pos);
862	        for (i = 0; i < SF_SUB_ID_MAX; i++) {
863	            if (pos->sensor_obj_registered[i] == 1) {
864	                soft_fault_event_free(&pos->sensor_event_queue[i]);
865	            }
866	        }
867	        soft_one_dev_exit(pos);
868	        ka_list_del(&pos->list);
869	        dbl_kfree(pos);
870	        pos = NULL;
871	    }
872	}
873	
874	void soft_dev_exit(void)
875	{
876	    int i, j;
877	    struct soft_dev_client *client = NULL;
878	    struct drv_soft_ctrl *soft_ctrl = soft_get_ctrl();
879	
880	    for (i = 0; i < ASCEND_DEV_MAX_NUM; i++) {
881	        ka_task_mutex_lock(&soft_ctrl->mutex[i]);
882	        for (j = SF_SENSOR_USER; j < SF_USER_MAX; j++) {
883	            client = soft_ctrl->s_dev_t[i][j];
884	            soft_dev_free_registered_dev(client);
885	            client->registered = 0;
886	            client->node_num = 0;
887	            client->pid = -1;
888	        }
889	
890	        soft_ctrl->user_num[i] = 0;
891	        ka_task_mutex_unlock(&soft_ctrl->mutex[i]);
892	    }
893	
894	    return;
895	}
896	
897	void soft_client_release(int owner_pid)
898	{
899	    int i, j;
900	    unsigned int user_num;
901	    struct soft_dev_client *client = NULL;
902	    struct drv_soft_ctrl *soft_ctrl = soft_get_ctrl();
903	
904	    for (i = 0; i < ASCEND_DEV_MAX_NUM; i++) {
905	        ka_task_mutex_lock(&soft_ctrl->mutex[i]);
906	        user_num = soft_ctrl->user_num[i];
907	        if (user_num == 0) {
908	            ka_task_mutex_unlock(&soft_ctrl->mutex[i]);
909	            continue;
910	        }
911	        for (j = SF_SENSOR_USER; j < SF_USER_MAX; j++) {
912	            client = soft_ctrl->s_dev_t[i][j];
913	            if ((client->registered == 0) || (client->pid != owner_pid)) {
914	                continue;
915	            }
916	            soft_dev_free_registered_dev(client);
917	            soft_drv_event("release one process success. (dev_id=%d; user_id=%d; owner_pid=%d)\n", i, j, owner_pid);
918	            client->registered = 0;
919	            client->node_num = 0;
920	            client->pid = -1;
921	            soft_ctrl->user_num[i]--;
922	            break;
923	        }
924	        ka_task_mutex_unlock(&soft_ctrl->mutex[i]);
925	    }
926	
927	    return;
928	}
